import { watchDom } from '../core/observer';
import { wasApplied, markApplied } from '../utils/dom';

function enhanceOsd() {
    const osd = document.querySelector(
        '.videoOsdPage, .osdControls, .videoPlayerContainer'
    );

    if (!osd || wasApplied(osd, 'ptvOsd')) return;

    markApplied(osd, 'ptvOsd');
    osd.classList.add('ptv-osd');
}

watchDom(enhanceOsd);
enhanceOsd();
